import{_ as t,o as r,c as a,ao as i}from"./chunks/framework.BzF2yrnJ.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem.md","filePath":"ecosystem.md","lastUpdated":null}'),o={name:"ecosystem.md"};function l(s,e,n,h,c,d){return r(),a("div",null,[...e[0]||(e[0]=[i('<h2 id="The-wider-ecosystem" tabindex="-1">The wider ecosystem <a class="header-anchor" href="#The-wider-ecosystem" aria-label="Permalink to &quot;The wider ecosystem {#The-wider-ecosystem}&quot;">​</a></h2><p>The WaterLily ecosystem is growing, with a number of packages that extend the core functionality of WaterLily. These include:</p><ul><li><p><a href="https://github.com/WaterLily-jl/LilyPad.jl" target="_blank" rel="noreferrer"><strong>LilyPad.jl</strong></a> – a semi-Lagrangian momentum-step variant of WaterLily for real-time simulations.</p></li><li><p><a href="https://github.com/WaterLily-jl/ParametricBodies.jl" target="_blank" rel="noreferrer"><strong>ParametricBodies.jl</strong></a> – bodies defined by parametric curves and NURBS rather than by a distance function, including bodies that deform while the simulation runs. Repositories for geometry, boundary conditions, and visualization</p></li><li><p><a href="https://github.com/WaterLily-jl/WaterLilyMeshBodies.jl" target="_blank" rel="noreferrer"><strong>WaterLilyMeshBodies.jl</strong></a> – tools to import mesh-defined geometries into WaterLily.</p></li><li><p><a href="https://github.com/WaterLily-jl/BiotSavartBCs.jl" target="_blank" rel="noreferrer"><strong>BiotSavartBCs.jl</strong></a> – replaces the domain boundary condition with a Biot-Savart evaluation of the velocity induced by the vorticity in the domain, so a much smaller domain behaves as if it were unbounded. Useful for freely moving bodies and for forces that are sensitive to blockage.</p></li><li><p><a href="https://github.com/WaterLily-jl/Pathlines.jl" target="_blank" rel="noreferrer"><strong>Pathlines.jl</strong></a> – Pathline visualization tools for WaterLily simulations, allows to track the motion of fluid particles over time.</p></li><li><p><a href="https://github.com/WaterLily-jl/WaterLilyNarrowBand.jl" target="_blank" rel="noreferrer"><strong>WaterLilyNarrowBand.jl</strong></a> – Measure moving bodies faster using a narrow band around their surface.</p></li></ul><p>&lt;!– CoupledSimulations.jl is private for now, so its link fails the link checker. Restore the entry once it is public:</p><ul><li><a href="https://github.com/WaterLily-jl/CoupledSimulations.jl" target="_blank" rel="noreferrer"><strong>CoupledSimulations.jl</strong></a> – Couples WaterLily with other simulation codes, such as structural solvers, to allow for fluid-structure interaction simulations.</li></ul><p>–&gt;</p>',6)])])}const p=t(o,[["render",l]]);export{m as __pageData,p as default};
